class Pendaftaran {
    private static final Logger log = LoggerFactory.getLogger(Pendaftaran.class);
    private final List<String> pengguna = new ArrayList<>();

    void daftar(String nama, String email, String sandi) {
        if (!email.contains("@")) {
            log.warn("Pendaftaran {} ditolak: email tidak valid", nama);
            return;
        }
        try {
            simpan(nama);
            log.info("Pengguna baru mendaftar: {} ({})", nama, email);
        } catch (IllegalStateException e) {
            log.error("Gagal menyimpan pengguna {}", nama, e);
        }
    }

    private void simpan(String nama) {
        if (pengguna.size() >= 2) {
            throw new IllegalStateException("kuota pengguna penuh");
        }
        pengguna.add(nama);
    }
}

