import java.util.*;

import org.slf4j.*;

public class Main {
    private static final Logger log = LoggerFactory.getLogger(Main.class);

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            String pesanan = d[0];
            String kartu = d[1];
            int jumlah = Integer.parseInt(d[2]);
            String akhir = kartu.substring(kartu.length() - 4);
            if (jumlah > 5000000) {
                log.warn("Pembayaran pesanan {} ditolak: jumlah {} melebihi batas", pesanan, jumlah);
            } else {
                log.info("Pembayaran pesanan {} berhasil: {} dengan kartu akhiran {}", pesanan, jumlah, akhir);
            }
        }
    }
}
